@torch.jit.script
def _normalized_gru_sequence(projected: torch.Tensor, weight_hh: torch.Tensor,
                             bias_hh: torch.Tensor, gate_scale: torch.Tensor,
                             gate_bias: torch.Tensor):
    hidden = projected.new_zeros((projected.size(0), weight_hh.size(1)))
    outputs = torch.jit.annotate(list[torch.Tensor], [])
    width = weight_hh.size(1)
    for t in range(projected.size(1)):
        recurrent = torch.nn.functional.linear(hidden, weight_hh, bias_hh)
        ir, iz, inn = projected[:, t].chunk(3, dim=-1)
        hr, hz, hn = recurrent.chunk(3, dim=-1)
        reset = torch.sigmoid(torch.nn.functional.layer_norm(
            ir + hr, [width], gate_scale[0], gate_bias[0], 1e-5))
        update = torch.sigmoid(torch.nn.functional.layer_norm(
            iz + hz, [width], gate_scale[1], gate_bias[1], 1e-5))
        candidate = torch.tanh(torch.nn.functional.layer_norm(
            inn + reset * hn, [width], gate_scale[2], gate_bias[2], 1e-5))
        hidden = (1.0 - update) * candidate + update * hidden
        outputs.append(hidden)
    return torch.stack(outputs, dim=1), hidden


class LayerNormGRULayer(nn.Module):
    def __init__(self, hidden_units: int):
        super().__init__()
        self.weight_ih = nn.Parameter(torch.empty(3 * hidden_units, hidden_units))
        self.weight_hh = nn.Parameter(torch.empty(3 * hidden_units, hidden_units))
        self.bias_ih = nn.Parameter(torch.empty(3 * hidden_units))
        self.bias_hh = nn.Parameter(torch.empty(3 * hidden_units))
        self.gate_scale = nn.Parameter(torch.ones(3, hidden_units))
        self.gate_bias = nn.Parameter(torch.zeros(3, hidden_units))
        bound = hidden_units ** -0.5
        for parameter in (self.weight_ih, self.weight_hh, self.bias_ih, self.bias_hh):
            nn.init.uniform_(parameter, -bound, bound)

    def forward(self, inputs: torch.Tensor):
        projected = torch.nn.functional.linear(inputs, self.weight_ih, self.bias_ih)
        return _normalized_gru_sequence(
            projected, self.weight_hh, self.bias_hh, self.gate_scale, self.gate_bias)


class LayerNormGRU(nn.Module):
    def __init__(self, hidden_units: int, num_layers: int, dropout: float):
        super().__init__()
        self.layers = nn.ModuleList([
            LayerNormGRULayer(hidden_units) for _ in range(num_layers)
        ])
        self.interlayer_dropout = nn.Dropout(dropout)

    def forward(self, inputs: torch.Tensor):
        out = inputs
        final_states = []
        for index, layer in enumerate(self.layers):
            out, hidden = layer(out)
            final_states.append(hidden)
            if index + 1 < len(self.layers):
                out = self.interlayer_dropout(out)
        return out, torch.stack(final_states, dim=0)


